import unittest

from sample import is_authorized


class AuthorizationTest(unittest.TestCase):
    def test_admin_is_authorized(self):
        self.assertIs(is_authorized("admin"), True)

    def test_other_roles_are_denied(self):
        for role in ("user", "viewer", "guest", "superadmin", "unknown", ""):
            with self.subTest(role=role):
                self.assertIs(is_authorized(role), False)

    def test_role_must_match_exactly(self):
        for role in ("Admin", "ADMIN", " admin", "admin ", "admin\n"):
            with self.subTest(role=role):
                self.assertIs(is_authorized(role), False)

    def test_missing_role_is_denied(self):
        self.assertIs(is_authorized(None), False)


if __name__ == "__main__":
    unittest.main()
